import { useState, useRef, useEffect } from "react";

function App() {
  const [selectedCard, setSelectedCard] = useState(null);
  const [primeNumber, setPrimeNumber] = useState("");
  const [streamLogs, setStreamLogs] = useState([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const streamRef = useRef(null);

  const questions = [
    {
      id: 1,
      title: "Prime Pattern Discovery",
      description: "Find the palindromic prime 123...i...321 where i is between 1000-3000",
      color: "from-purple-600 to-pink-600",
    },
    {
      id: 2,
      title: "Repunit Primes",
      description: "Find 5 primes of the form 111...1 (N ones) between N=2 and N=1040",
      color: "from-blue-600 to-cyan-600",
    },
    {
      id: 3,
      title: "Mersenne Primes",
      description: "Find primes of the form 2^p - 1 between p=2201 and p=2299",
      color: "from-green-600 to-emerald-600",
    },
    {
      id: 4,
      title: "Brocard's Conjecture",
      description: "Find 4 primes between squares of consecutive primes",
      color: "from-red-600 to-orange-600",
    },
    {
      id: 5,
      title: "Palindromic Primes",
      description: "Find a palindromic prime with at least 50 digits",
      color: "from-indigo-600 to-purple-600",
    },
    {
      id: 6,
      title: "Perfect Numbers",
      description: "Prove 2^(p-1)(2^p - 1) yields a perfect number using primes from Q3",
      color: "from-yellow-600 to-orange-600",
    },
    {
      id: 7,
      title: "Prime Conjectures",
      description: "Test famous prime conjectures on numbers with 50+ digits",
      color: "from-teal-600 to-green-600",
    },
  ];

  const startStream = async (endpoint) => {
    setIsStreaming(true);
    setStreamLogs([]);

    try {
      const response = await fetch(endpoint);
      const reader = response.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              setStreamLogs(prev => [...prev, data]);
            } catch (e) {
              // Skip malformed JSON
            }
          }
        }
      }
    } catch (error) {
      setStreamLogs(prev => [...prev, { type: 'error', message: error.message }]);
    } finally {
      setIsStreaming(false);
    }
  };

  const testPrimeStream = () => {
    if (!primeNumber.trim()) return;
    startStream(`http://localhost:8000/api/testprime/stream?n=${primeNumber}`);
  };

  const runQuestion1 = () => {
    startStream('http://localhost:8000/api/question1/stream');
  };

  const stopStream = () => {
    if (streamRef.current) {
      streamRef.current.abort();
    }
    setIsStreaming(false);
  };

  const formatLogEntry = (log) => {
    switch (log.type) {
      case 'test':
        return `🎯 Round ${log.round}: Testing base ${log.base}, initial value: ${log.initial_value}`;
      case 'witness':
        if (log.result === 'composite') {
          return `❌ Base ${log.base} is a WITNESS (proves composite)`;
        } else {
          return `✅ Base ${log.base} passed (found ${log.value})`;
        }
      case 'square':
        return `  └─ Square ${log.iteration}: ${log.value}`;
      case 'small_prime_check':
        return log.result ? '✅ Found in small primes list' : '❌ Divisible by small prime';
      case 'result':
        return log.prime ? 
          `🎉 RESULT: ${log.reason}` : 
          `💥 RESULT: NOT PRIME (${log.reason})`;
      case 'checking':
        return `🔍 Checking i=${log.i}, number has ${log.length} digits`;
      case 'found':
        return `🏆 FOUND PRIME: i=${log.i}, number=${log.number} (via ${log.method})`;
      case 'info':
        return `ℹ️ ${log.message}`;
      case 'error':
        return `❌ Error: ${log.message}`;
      default:
        return `📝 ${log.message || JSON.stringify(log)}`;
    }
  };

  if (selectedCard) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-purple-900 to-violet-800 text-white">
        <div className="container mx-auto px-6 py-8">
          <button
            onClick={() => setSelectedCard(null)}
            className="mb-6 flex items-center text-purple-300 hover:text-white transition-colors"
          >
            <span className="text-2xl mr-2">←</span>
            Back to Dashboard
          </button>

          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 border border-white/20">
            <h1 className="text-4xl font-bold mb-4 bg-gradient-to-r from-purple-400 to-pink-400 bg-clip-text text-transparent">
              Question {selectedCard.id}: {selectedCard.title}
            </h1>
            <p className="text-purple-200 text-lg mb-8">{selectedCard.description}</p>

            {selectedCard.id === 1 && (
              <div className="space-y-6">
                <button
                  onClick={runQuestion1}
                  disabled={isStreaming}
                  className="px-6 py-3 bg-gradient-to-r from-purple-600 to-pink-600 rounded-xl font-semibold disabled:opacity-50 hover:scale-105 transition-transform"
                >
                  {isStreaming ? 'Running...' : 'Start Search'}
                </button>
              </div>
            )}

            {streamLogs.length > 0 && (
              <div className="mt-8">
                <div className="bg-black/30 rounded-2xl p-6 border border-white/10">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-semibold">Live Stream</h3>
                    {isStreaming && (
                      <div className="flex items-center">
                        <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse mr-2"></div>
                        <span className="text-green-400">Streaming...</span>
                      </div>
                    )}
                  </div>
                  <div className="space-y-2 max-h-96 overflow-y-auto font-mono text-sm">
                    {streamLogs.map((log, index) => (
                      <div key={index} className="text-gray-300">
                        {formatLogEntry(log)}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-purple-900 to-violet-800 text-white">
      <div className="container mx-auto px-6 py-12">
        {/* Header */}
        <div className="text-center mb-16">
          <h1 className="text-6xl font-bold mb-6 bg-gradient-to-r from-purple-400 via-pink-400 to-cyan-400 bg-clip-text text-transparent">
            Prime Number Playground
          </h1>
          <p className="text-xl text-purple-200 max-w-3xl mx-auto">
            Explore fascinating prime number problems with real-time Miller-Rabin testing and witness visualization
          </p>
        </div>

        {/* Prime Tester */}
        <div className="mb-16 max-w-2xl mx-auto">
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-8 border border-white/20">
            <h2 className="text-3xl font-bold mb-6 text-center">🧮 Prime Tester</h2>
            <div className="flex gap-4 mb-6">
              <input
                type="text"
                placeholder="Enter a number to test..."
                value={primeNumber}
                onChange={(e) => setPrimeNumber(e.target.value)}
                className="flex-1 px-4 py-3 bg-white/10 border border-white/20 rounded-xl text-white placeholder-purple-300 focus:outline-none focus:border-purple-400"
              />
              <button
                onClick={testPrimeStream}
                disabled={isStreaming || !primeNumber.trim()}
                className="px-6 py-3 bg-gradient-to-r from-cyan-600 to-blue-600 rounded-xl font-semibold disabled:opacity-50 hover:scale-105 transition-transform"
              >
                {isStreaming ? 'Testing...' : 'Test Prime'}
              </button>
            </div>

            {streamLogs.length > 0 && (
              <div className="bg-black/30 rounded-2xl p-6 border border-white/10">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-xl font-semibold">Miller-Rabin Test Results</h3>
                  {isStreaming && (
                    <div className="flex items-center">
                      <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse mr-2"></div>
                      <span className="text-green-400">Testing...</span>
                    </div>
                  )}
                </div>
                <div className="space-y-2 max-h-64 overflow-y-auto font-mono text-sm">
                  {streamLogs.map((log, index) => (
                    <div key={index} className="text-gray-300">
                      {formatLogEntry(log)}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Question Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {questions.map((question) => (
            <div
              key={question.id}
              onClick={() => setSelectedCard(question)}
              className="group cursor-pointer transform hover:scale-105 transition-all duration-300"
            >
              <div className={`bg-gradient-to-br ${question.color} rounded-2xl p-1`}>
                <div className="bg-gray-900/80 rounded-2xl p-6 h-full backdrop-blur">
                  <div className="text-3xl mb-4">🔢</div>
                  <h3 className="text-xl font-bold mb-3">{question.title}</h3>
                  <p className="text-gray-300 text-sm leading-relaxed">
                    {question.description}
                  </p>
                  <div className="mt-4 text-right">
                    <span className="text-2xl opacity-50 group-hover:opacity-100 transition-opacity">
                      →
                    </span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default App;
